---快速装备按钮点击回调
function CardProgressionEquip:BtnEquipOnClickHandler()
    local equips = checkTable(self._cardEntity.equipPart2Dojo)
    if next(equips) ~= nil then
        self:SaveAniEquips()
        self:RecordCardPoint()
        -- 清空装备
        for k, v in pairs(equips) do
            EquipComp:RemoveCardOnEquip(self.cardDojo.id, v.id, k)
            self.equipIdList[k] = 0
        end
        self:GetRightPanelEquipmentEnv():SetEquipIdList(self.equipIdList)

        local equipIdList = {}
        for i = 1, CardProgressionConstants.EquipmentNum do
            equipIdList[tostring(i)] = 0
        end
        CardProgressionMgr:RequestOverseaEquipmentEquip({
            playerCardId = self.cardDojo.id, equipment = table.serialize(equipIdList)
        })
    else
        -- 快速装备
        self:QuicklyEquip()
    end
end

