---装备按钮点击回调
---@param index integer 装备序号
function CardProgressionEquip:BtnEquipmentOnClickHandler(index)
    if self.part ~= index then
        self:RefreshEquipBtnSelectState(self.part, false)
        self:RefreshEquipBtnSelectState(index, true)
        self.part = index
    end
    
    -- 页签切换
    local mbEnv = self:GetRightPanelEquipmentEnv()
    if mbEnv == nil then return end
    mbEnv:SwitchPart(index)
    
    self:SwitchRightPanel(RightPanelType.EQUIPMENT_LIST)
    
    if checkInt(self.equipIdList[index]) ~= 0 then
        -- 装备详情
        local curDojo = EquipComp:GetEquipById(self.equipIdList[index])
        self:LoadComparedView(curDojo, nil, EquipType.Equip, index, Bind(self, self.HideSelectIndex))
    end
end

function CardProgressionEquip:OnCellClickAction(backpackDataId, part, equipType)
    if backpackDataId <= 0 then return end
    local equipIdList = self.equipIdList
    local equipPart = part or self.part
    local curDojo = EquipComp:GetEquipById(equipIdList[equipPart])
    local compareDojo = EquipComp:GetEquipById(backpackDataId)
    if curDojo and checkInt(curDojo.id) == checkInt(compareDojo.id) then
        compareDojo = nil
    end
        
    self:LoadComparedView(curDojo, compareDojo, equipType, equipPart, Bind(self, self.HideSelectIndex))
end

function CardProgressionEquip:OnUpdatePartAction(part)
    self:SwitchPart(part)
end

function CardProgressionEquip:OnEventOperateEquipOrCore(params, equipType, direction)
    local isLeft = direction == 1
    local isRecast = direction == 3
    local status = params.status
    local dojo   = params.dojo
    local part   = params.part
    local playerCardId = self.cardDojo.id

    if isRecast then
        self._selectedEquipmentId = checkInt(params.dojo.id)
        EquipUtils.EnterEquipmentRecastDialog(dojo)
        return
    end

    if direction == 4 then
        self._selectedEquipmentId = checkInt(params.dojo.id)
        EquipUtils.EnterEquipmentReforgeDialog(dojo)
        return
    end
    
    if isLeft then
        self._selectedEquipmentId = checkInt(params.dojo.id)
        self:EnterCultivateEquipDialog(dojo)
        return
    end
    
    local t = {
        [Status.CultivateAndInstall] = Status.Install,
        [Status.CultivateAndReplace] = Status.Replace,
        [Status.CultivateAndUninstall] = Status.Uninstall,
    }
    local realStatus = t[status] or status
    self:UpdateCardOnEquipOrCore(playerCardId, dojo, equipType, part, realStatus)
end

function CardProgressionEquip:SaveUIState()
    ---@type UICultivateEquipBackpackNodeMB
    local mbEnv = self:GetRightPanelEquipmentEnv()
    if mbEnv == nil then return end
    local backpackCacheData = mbEnv:SaveUIState()
    local parameters = self.controller.Argument.parameters or {}
