function CardProgressionEquip:OnEventStarUpFinishListener(equipDojo)
    if isNull(equipDojo) then return end
    local equipIdList = self.equipIdList
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local equipPart = equipVo.part
    local curDojo = EquipComp:GetEquipById(equipIdList[equipPart])
    local compareDojo = equipDojo
    if curDojo and checkInt(curDojo.id) == checkInt(compareDojo.id) then
        compareDojo = nil
    end
    self:LoadComparedView(curDojo, compareDojo, EquipType.Equip, equipVo.part, Bind(self, self.HideSelectIndex))
end

