function CardProgressionEquip:LoadComparedView(curDojo, compareDojo, equipType, part, closeCb)
    if self.ComparedView then
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        return
    end
    if self.ComparedViewCo then
        return
    end
    self.ComparedViewCo = cs_coroutine.start(function()
        self.ComparedView = GameUtils.LoadBundleAsyncById(EquipComparedViewPrefabId, self.Container.gameObject, false, true)
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        local OrderTrackerType = typeof(CS.Engine.UI.OrderTracker)
        ---@type Engine.UI.OrderTracker
        local orderTracker = KTool.GetOrAddComponent(self.ComparedView.gameObject, OrderTrackerType)
        orderTracker.addSortingOrder = 1001
        self.ComparedViewCo = nil
    end)
end

function CardProgressionEquip:StopComparedViewCo()
    if not isNull(self.ComparedViewCo) then
        cs_coroutine.stop(self.ComparedViewCo)
        self.ComparedViewCo = nil
    end
end

function CardProgressionEquip:StopAniCo()
    if not isNull(self._aniCo) then
        cs_coroutine.stop(self._aniCo)
        self._aniCo = nil
    end
end

function CardProgressionEquip:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
    ---@type UICultivateEquipComparedView
    local mbEnv = CfUtils.GetLuaScr(self.ComparedView, "Game.CardProgression.Equip.CardProgressionEquipmentComparedNode")
    if not isNull(mbEnv) then
        mbEnv:SetCloseCb(closeCb)
        mbEnv:RefreshUI(self.equipIdList, curDojo, compareDojo, equipType, part, self.cardDojo.id)
        GameUtils.UpdateUIShowState(self.ComparedView.gameObject, true)
        CfUtils.SetNavHomeShow(false, false)
    end
end

function CardProgressionEquip:UpdateCardOnEquipOrCore(playerCardId, dojo, equipType, part, status)
    local isUninstall = status == Status.Uninstall
    local isEquip = equipType == EquipType.Equip
    local id = checkNumber(dojo.id)

    self:SaveAniEquips()
    self:RecordCardPoint()
    local equipmentCoreDojo
    if isEquip then
        local func = isUninstall and EquipComp.RemoveCardOnEquip or EquipComp.AddCardOnEquip
        func(EquipComp, playerCardId, id, part)

        local equipId = isUninstall and 0 or id
        self.equipIdList[part] = equipId
        self:GetRightPanelEquipmentEnv():SetEquipIdList(self.equipIdList)

        equipmentCoreDojo = EquipComp:GetEquipCoreById(self.cardDojo.equipmentCore)
    else
        local func = isUninstall and EquipComp.RemoveCardOnEquipCore or EquipComp.AddCardOnEquipCore
        func(EquipComp, playerCardId, id)
    end
    local equipIdList = {}
    for i = 1, CardProgressionConstants.EquipmentNum do
        equipIdList[tostring(i)] = self.equipIdList[i]
    end
    
    CardProgressionMgr:RequestOverseaEquipmentEquip({
        playerCardId = playerCardId, equipment = table.serialize(equipIdList)
    })
end

function CardProgressionEquip:InitCardDojo(playerCardId)
    
    ---@type CardDojo
    local cardDojo = CardComp:GetCardById(playerCardId)
    self.cardDojo = cardDojo
    return cardDojo
end

function CardProgressionEquip:RefreshBackpackDataAndRefreshList(newId, oldId, part)
    ---@type UICultivateEquipBackpackNodeMB
    local mbEnv = self:GetRightPanelEquipmentEnv()
    if mbEnv == nil then return end
    mbEnv:RefreshBackpackDataAndRefreshList(newId, oldId, part)
end

function CardProgressionEquip:ExecuteEquipmentEquip()
    ---@type CardDojo
    local cardDojo            = self.cardDojo
    local playerCardId        = cardDojo.id
    local equipIdList         = self.equipIdList
    local originalEquipIdList = self.originalEquipIdList
    local isChange            = false
    local equipmentIdList     = {}

    for i = 1, CardProgressionConstants.EquipmentNum do
        local originalEquipId = checkNumber(originalEquipIdList[i])
        local equipId = checkNumber(equipIdList[i])
        if originalEquipId ~= equipId then
            isChange = true
        end
        equipmentIdList[tostring(i)] = equipId
    end

    local equipmentCore = checkNumber(cardDojo.equipmentCore)
    if not isChange then
        isChange = self.originalEquipmentCoreId ~= equipmentCore
    end

    if isChange then
        CardProgressionMgr:RequestOverseaEquipmentEquip({playerEquipmentCoreId = equipmentCore, playerCardId = playerCardId, equipment = table.serialize(equipmentIdList) })
    end
end

function CardProgressionEquip:EnterCultivateEquipDialog(playerEquipId)
    EquipUtils.EnterCultivateEquipDialog(playerEquipId)
end

function CardProgressionEquip:SwitchPart(part)
    if self.part == part then return end
    
    self:RefreshEquipBtnSelectState(self.part, false)
    self:RefreshEquipBtnSelectState(part, true)
    self.part = part
end



function CardProgressionEquip:SwitchRightPanel(panelType)
    if panelType == self._rightPanel then return end

    if panelType == RightPanelType.EQUIPMENT_LIST then
        KTool.SetActive(self.RightPanelEquipment, true)
        KTool.SetActive(self.RightPanelSuit, false)
        CfUtils.PlayAnimation(self.Root, "CultivateOverseaEquipmentDialogPanelEquipment")
        Events.Broadcast("CardProgressionConstants.EventNames.SetArrowShowState", true)
        CfUtils.SetActive(self.BtnEquip, true)
        CfUtils.SetActive(self.BtnChange, true)
        self:RefreshEquipBackpack()
    elseif panelType == RightPanelType.EQUIPMENT_EXCHANGE then
        KTool.SetActive(self.RightPanelEquipment, false)
        KTool.SetActive(self.RightPanelSuit, true)
        CfUtils.PlayAnimation(self.Root, "CultivateOverseaEquipmentDialogPanelSuit")
        Events.Broadcast("CardProgressionConstants.EventNames.SetArrowShowState", false)
        self:RefreshExchangeNode()
        CfUtils.SetActive(self.BtnEquip, false)
        CfUtils.SetActive(self.BtnChange, false)
    end
    self._rightPanel = panelType
end

function CardProgressionEquip:RefreshExchangeNode()
    self._selectedExchangeIdx = nil -- 清空选中状态
    local mbEnv = self:GetRightPanelExchangeEnv()
    if mbEnv == nil then return end
    
    mbEnv:ClearSelectedIndex()
    mbEnv:RefreshUI(self._cardId)
end

---播放进入动画
function CardProgressionEquip:PlayEquipmentAnimation()
    local cardId = checkInt(self.cardDojo.cardId)
    if cardId == self._cardId then return end

    for i, v in ipairs(self.equipIdList) do
        local equipGo = self.EquippingTankItem:Find(string.format('BtnTankGroup%d', i))
        local scr = CfUtils.GetLuaScr(equipGo, "Game.CardProgression.Equip.CardProgressionCardEquipBtnNode")
        if scr then
            scr:SetEffectState(checkInt(v) ~= 0)
        end
    end

    local animation = self.Root.transform:GetComponent(typeof(CS.UnityEngine.Animation))
    if not animation then
        return
    end
    animation:Stop()
    animation:Play('CultivateOverseaEquipmentDialogGo')
end

---播放装备切换技动画
function CardProgressionEquip:PlayEquipmentBtnSwitchAnimation(part)
    local equipGo = self.EquippingTankItem:Find(string.format('BtnTankGroup%d', part))
    local scr = CfUtils.GetLuaScr(equipGo, "Game.CardProgression.Equip.CardProgressionCardEquipBtnNode")
