---记录卡牌战斗力
function CardProgressionEquip:RecordCardPoint()
    self._cardPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(self._cardEntity))
end

---检查卡牌战斗力
function CardProgressionEquip:CheckCardPoint()
    if isNull(self._cardPoint) then return end
    
    local cardPoint = checkInt(FormulaUtils.CalcCardCombatEffectiveness(self._cardEntity))
    if self._cardPoint ~= cardPoint then
        CardProgressionUtils.ChangePointToast(cardPoint - self._cardPoint)
    end
    self._cardPoint = nil
end

---快速装备
function CardProgressionEquip:QuicklyEquip()
    local allEquips = EquipComp:GetAllEquips()
    local equipmentsGroup = {}
    local pickEquipments = {}
    for i = 1, CardProgressionConstants.EquipmentNum do
        table.insert(equipmentsGroup, {
            equipments = {},
            maxPoint = {id = 0, point = 0}
        })
    end

    
    ---生成 养成属性提供者对应的属性加成类型配置 和 养成所有模块常量属性和
    local equipIdList = {}
    for i = 1, CardProgressionConstants.EquipmentNum do
        equipIdList[i] = 0
    end
    for _, v in ipairs(allEquips) do
        if checkInt(v.playerCardId) == 0 then
            local point = checkInt(FormulaUtils.CalcEquipDojoCombatEffectiveness(v))
            local equipVo = cardConfMgr:GetEquipVoById(v.equipmentId)
            local partData = equipmentsGroup[checkInt(equipVo.part)]
            if not partData.equipments[tostring(equipVo.suitId)] or point > partData.equipments[tostring(equipVo.suitId)].point then
                partData.equipments[tostring(equipVo.suitId)] = {
                    id = v.id,
                    point = point
                }
            end
            if point > partData.maxPoint.point then
                partData.maxPoint.id = v.id
                partData.maxPoint.point = point
            end
        end 
    end
    
    -- 根据角色推荐的套装顺序筛选
    local cardVo = cardConfMgr:GetCardByRefId(self._cardEntity.cardId)
    local autoEquip = cardVo.autoEquip
    for _, suitId in ipairs(autoEquip) do
        local emptyNum = CardProgressionConstants.EquipmentNum - table.count(pickEquipments)
        if emptyNum == 0 then
            break
        end
        local suitVo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", suitId)
        local suitNum = checkInt(suitVo.suitNum)
        if emptyNum >= suitNum then
           local suitGroup = {}
            for part, partData in ipairs(equipmentsGroup) do
                if not pickEquipments[tostring(part)] and partData.equipments[tostring(suitId)] then
                    partData.equipments[tostring(suitId)].part = part
                    table.insert(suitGroup, partData.equipments[tostring(suitId)])
                end
            end
            if #suitGroup >= suitNum then
                table.sort(suitGroup, function (a, b)
                    return a.point > b.point
                end)
                for i = 1, suitNum do
                    pickEquipments[tostring(suitGroup[i].part)] = suitGroup[i].id
                end
            end
        end
    end
    
    -- 空位置填充最高战力装备
    for i = 1, CardProgressionConstants.EquipmentNum do
        if not pickEquipments[tostring(i)] then
            pickEquipments[tostring(i)] = equipmentsGroup[i].maxPoint.id
        end
    end
    
    local isEmpty = true
    for i, v in pairs(pickEquipments) do
        if checkInt(v) > 0 then
            isEmpty = false
            break
        end
    end
    if isEmpty then
        GameUtils.Toast(localize("没有可穿戴的装备"))
        return
    end
    
    self:SaveAniEquips()
    self:RecordCardPoint()
    for i = 1, CardProgressionConstants.EquipmentNum do
        if checkInt(pickEquipments[tostring(i)]) > 0 then
            EquipComp:AddCardOnEquip(self.cardDojo.id, pickEquipments[tostring(i)], i)
            self.equipIdList[i] = self.cardDojo.id
        end
    end
    self:GetRightPanelEquipmentEnv():SetEquipIdList(self.equipIdList)
    CardProgressionMgr:RequestOverseaEquipmentEquip({
        playerCardId = self.cardDojo.id, equipment = table.serialize(pickEquipments)
    })
end

---保存一份请求前数据，用于播放更换动画
function CardProgressionEquip:SaveAniEquips()
    self._aniEquips = clone(self._cardEntity.equipPart2Dojo)
end
